#pragma once
#include <string>
#include <vector>

#include "FlashcardCardActions.h"
#include "activities/Activity.h"
#include "util/ButtonNavigator.h"

// Settings > Marked and suspended, to clean decks up (e.g. ones generated by
// AI). First level: actions on every deck at once, then each deck with its
// counts. A deck opens its own actions and its marked or suspended cards; a
// card offers mark/unmark, suspend/reactivate, reset and delete. Changes are
// written to the deck files at once, card by card (no deck is loaded).
class FlashcardFlaggedActivity final : public Activity {
  static constexpr size_t MAX_LISTED = 80;  // cards listed for one deck; more show up after a clean-up

  enum class View : uint8_t { Decks, Deck, CardActions, Confirm };
  enum class Act : uint8_t {
    None,
    OpenDeck,
    OpenCard,
    DeleteAllMarked,
    ReactivateAll,
    DeleteMarked,
    UnmarkAll,
    ReactivateSuspended,
    ToggleMark,
    ToggleSuspend,
    Reset,
    Delete
  };
  struct Row {
    Act act = Act::None;  // None: section label
    int index = -1;       // deck (Decks view) or card (Deck view)
  };

  ButtonNavigator buttonNavigator;
  View view = View::Decks;
  View confirmFrom = View::Decks;
  std::vector<FlashcardCardActions::FlaggedCount> decks;
  uint32_t totalMarked = 0;
  uint32_t totalSuspended = 0;
  int openDeck = -1;  // index into decks
  std::vector<FlashcardCardActions::Flagged> cards;
  int openCard = -1;  // index into cards
  std::vector<Row> rows;
  int selected = 0;
  int decksSelected = 0;  // remembered while a deck is open
  int deckSelected = 0;   // remembered while a card's actions are open
  Act pendingConfirm = Act::None;
  std::string statusMsg;

  void loadDecks();
  void loadDeck();
  void buildRows();
  void moveTo(int index, int direction);
  void activate(Act act);
  void run(Act act);
  void back();
  const FlashcardCardActions::FlaggedCount* currentDeck() const;

 public:
  explicit FlashcardFlaggedActivity(GfxRenderer& renderer, MappedInputManager& mappedInput)
      : Activity("FlashcardFlagged", renderer, mappedInput) {}

  void onEnter() override;
  void loop() override;
  void render(RenderLock&&) override;
};
